modules.wpplang/compiler/codegen.py:
"""The Python code generator.

Walks the W++ AST and emits Python source.  It reads only the tree - there is
no keyword substitution anywhere in this module - so the mapping from W++ to
Python lives in exactly one place: the KEYWORDS table, consulted here when a
node names a W++ word.

While emitting, the generator records which W++ line each generated Python line
came from.  That map is what lets a Python exception be reported against the
W++ the author wrote.
"""

from ..keywords import KEYWORDS
from . import nodes as N

# The Python each W++ construct is written with.  Taken from the dictionary so
# the table stays the single source of truth.
PY = KEYWORDS

_CONSTANTS = {"nocap": "True", "cap": "False", "npc": "None"}


class SourceMap:
    """Which W++ line produced each generated Python line."""

    def __init__(self):
        self._to_wpp = {}

    def record(self, python_line, wpp_line):
        if wpp_line:
            self._to_wpp[python_line] = wpp_line

    def wpp_line_for(self, python_line):
        """The W++ line for a Python line, or the nearest one above it."""
        if python_line in self._to_wpp:
            return self._to_wpp[python_line]
        candidates = [line for line in self._to_wpp if line <= python_line]
        if not candidates:
            return None
        return self._to_wpp[max(candidates)]

    def as_dict(self):
        return dict(self._to_wpp)


def generate(program):
    """Generate Python source for a Program.  Returns (source, SourceMap)."""
    emitter = _Emitter()
    if program.body:
        emitter.statements(program.body)
    # An empty program generates nothing. `pass` is only needed to fill a block
    # that would otherwise be empty, and a whole file is not a block.
    return emitter.finish()


class _Emitter:
    def __init__(self):
        self.lines = []
        self.map = SourceMap()
        # How many physical lines have been written. An emitted statement can
        # occupy more than one - a triple-quoted string carries its own
        # newlines - so this cannot be inferred from len(self.lines).
        self.physical = 0

    # -- output

    def emit(self, text, indent, node=None):
        """Write one line of Python, on the W++ line it came from where it can.

        Statements are padded down to the line their W++ counterpart occupies.
        It costs a few blank lines and buys two things: `--emit` output that
        lines up with the source the author is reading, and a source map that
        is exact rather than approximate.  When a W++ line yields more than one
        Python line the alignment cannot hold, and the map carries the truth
        instead.
        """
        wanted = getattr(node, "line", None) if node is not None else None
        if wanted:
            while self.physical < wanted - 1:
                self.lines.append("")
                self.physical += 1

        self.lines.append("    " * indent + text)
        start = self.physical + 1
        self.physical += 1 + text.count(chr(10))
        if wanted:
            self.map.record(start, wanted)

    def finish(self):
        if not self.lines:
            return "", self.map
        return chr(10).join(self.lines) + chr(10), self.map

    # -- statements

    def statements(self, body, indent=0):
        if body is None:
            self.emit("pass", indent)
            return
        if not isinstance(body, list):
            body = [body]
        if not body:
            self.emit("pass", indent)
            return
        for statement in body:
            self.statement(statement, indent)

    def statement(self, node, indent):
        kind = type(node).__name__
        handler = getattr(self, "_" + kind, None)
        if handler is None:
            if kind == "_Sequence":
                for item in node.statements:
                    self.statement(item, indent)
                return
            raise NotImplementedError("no code generation for " + kind)
        handler(node, indent)

    def _FunctionDeclaration(self, node, indent):
        for decorator in node.decorators or []:
            self.emit("@" + self.expression(decorator), indent, node)
        header = "{}{} {}({})".format(
            "async " if node.is_async else "", PY["cook"], node.name,
            self.parameters(node.params))
        if node.returns is not None:
            header += " -> " + self.expression(node.returns)
        self.emit(header + ":", indent, node)
        self.statements(node.body, indent + 1)

    def _ClassDeclaration(self, node, indent):
        for decorator in node.decorators or []:
            self.emit("@" + self.expression(decorator), indent, node)
        pieces = [self.expression(base) for base in node.bases or []]
        pieces += [self.keyword_argument(item) for item in node.keywords or []]
        header = "class " + node.name
        if pieces:
            header += "(" + ", ".join(pieces) + ")"
        self.emit(header + ":", indent, node)
        self.statements(node.body, indent + 1)

    def _ReturnStatement(self, node, indent):
        if node.value is None:
            self.emit(PY["spill"], indent, node)
        else:
            self.emit("{} {}".format(PY["spill"], self.expression(node.value)),
                      indent, node)

    def _IfStatement(self, node, indent):
        for position, (condition, body) in enumerate(node.branches):
            word = PY["bet"] if position == 0 else PY["plotwist"]
            self.emit("{} {}:".format(word, self.expression(condition)),
                      indent, node)
            self.statements(body, indent + 1)
        if node.orelse is not None:
            self.emit(PY["nah"] + ":", indent, node)
            self.statements(node.orelse, indent + 1)

    def _ForStatement(self, node, indent):
        self.emit("{}{} {} in {}:".format(
            "async " if node.is_async else "", PY["spam"],
            self.target(node.target), self.expression(node.iterable)),
            indent, node)
        self.statements(node.body, indent + 1)
        if node.orelse is not None:
            self.emit(PY["nah"] + ":", indent, node)
            self.statements(node.orelse, indent + 1)

    def _WhileStatement(self, node, indent):
        self.emit("{} {}:".format(PY["grind"], self.expression(node.condition)),
                  indent, node)
        self.statements(node.body, indent + 1)
        if node.orelse is not None:
            self.emit(PY["nah"] + ":", indent, node)
            self.statements(node.orelse, indent + 1)

    def _BreakStatement(self, node, indent):
        self.emit(PY["dip"], indent, node)

    def _ContinueStatement(self, node, indent):
        self.emit(PY["skrrt"], indent, node)

    def _PassStatement(self, node, indent):
        self.emit("pass", indent, node)

    def _Assignment(self, node, indent):
        targets = " = ".join(self.target(target) for target in node.targets)
        self.emit("{} = {}".format(targets, self.expression(node.value)),
                  indent, node)

    def _AugmentedAssignment(self, node, indent):
        self.emit("{} {} {}".format(self.target(node.target), node.operator,
                                    self.expression(node.value)), indent, node)

    def _AnnotatedAssignment(self, node, indent):
        text = "{}: {}".format(self.target(node.target),
                               self.expression(node.annotation))
        if node.value is not None:
            text += " = " + self.expression(node.value)
        self.emit(text, indent, node)

    def _ExpressionStatement(self, node, indent):
        self.emit(self.expression(node.expression), indent, node)

    def _TryStatement(self, node, indent):
        self.emit("try:", indent, node)
        self.statements(node.body, indent + 1)
        for handler in node.handlers or []:
            header = "except"
            if handler.is_star:
                header += "*"
            if handler.type is not None:
                header += " " + self.expression(handler.type)
            if handler.name:
                header += " as " + handler.name
            self.emit(header + ":", indent, handler)
            self.statements(handler.body, indent + 1)
        if node.orelse is not None:
            self.emit(PY["nah"] + ":", indent, node)
            self.statements(node.orelse, indent + 1)
        if node.finalbody is not None:
            self.emit("finally:", indent, node)
            self.statements(node.finalbody, indent + 1)

    def _WithStatement(self, node, indent):
        pieces = []
        for item in node.items:
            text = self.expression(item.context)
            if item.target is not None:
                text += " as " + self.target(item.target)
            pieces.append(text)
        self.emit("{}with {}:".format("async " if node.is_async else "",
                                      ", ".join(pieces)), indent, node)
        self.statements(node.body, indent + 1)

    def _RaiseStatement(self, node, indent):
        text = "raise"
        if node.exception is not None:
            text += " " + self.expression(node.exception)
            if node.cause is not None:
                text += " from " + self.expression(node.cause)
        self.emit(text, indent, node)

    def _AssertStatement(self, node, indent):
        text = "assert " + self.expression(node.test)
        if node.message is not None:
            text += ", " + self.expression(node.message)
        self.emit(text, indent, node)

    def _ImportStatement(self, node, indent):
        pieces = [alias.name + (" as " + alias.asname if alias.asname else "")
                  for alias in node.names]
        self.emit("import " + ", ".join(pieces), indent, node)

    def _ImportFromStatement(self, node, indent):
        pieces = [alias.name + (" as " + alias.asname if alias.asname else "")
                  for alias in node.names]
        self.emit("from {}{} import {}".format(
            "." * (node.level or 0), node.module or "", ", ".join(pieces)),
            indent, node)

    def _GlobalStatement(self, node, indent):
        self.emit("global " + ", ".join(node.names), indent, node)

    def _NonlocalStatement(self, node, indent):
        self.emit("nonlocal " + ", ".join(node.names), indent, node)

    def _DeleteStatement(self, node, indent):
        self.emit("del " + ", ".join(self.target(t) for t in node.targets),
                  indent, node)

    def _MatchStatement(self, node, indent):
        self.emit("match {}:".format(self.expression(node.subject)), indent, node)
        for case in node.cases:
            header = "case " + case.pattern
            if case.guard is not None:
                header += " if " + self.expression(case.guard)
            self.emit(header + ":", indent + 1, case)
            self.statements(case.body, indent + 2)

    # -- parameters and arguments

    def parameters(self, params):
        pieces = []
        positional_only = [p for p in params if p.kind == "positional_only"]
        seen_keyword_only = False
        seen_vararg = False

        for index, param in enumerate(params):
            if param.kind == "vararg":
                pieces.append("*" + param.name)
                seen_vararg = True
                continue
            if param.kind == "kwarg":
                pieces.append("**" + param.name)
                continue
            if param.kind == "keyword_only" and not seen_vararg and not seen_keyword_only:
                pieces.append("*")
                seen_keyword_only = True

            text = param.name
            if param.annotation is not None:
                text += ": " + self.expression(param.annotation)
            if param.default is not None:
                text += ("=" if param.annotation is None else " = ") \
                    + self.expression(param.default)
            pieces.append(text)

            if positional_only and param is positional_only[-1]:
                pieces.append("/")
        return ", ".join(pieces)

    def keyword_argument(self, item):
        if item.name is None:
            return "**" + self.expression(item.value)
        return "{}={}".format(item.name, self.expression(item.value))

    def target(self, node):
        """A target is written the same way as an expression."""
        return self.expression(node)

    # -- expressions

    def expression(self, node):
        if node is None:
            return ""
        kind = type(node).__name__
        handler = getattr(self, "_e_" + kind, None)
        if handler is None:
            raise NotImplementedError("no code generation for " + kind)
        return handler(node)

    def _e_Literal(self, node):
        if node.kind == "constant":
            return _CONSTANTS[node.value]
        # Numbers and strings are emitted exactly as written, which is the only
        # correct thing to do with the contents of a string literal.
        return node.raw

    def _e_Identifier(self, node):
        # A W++ word standing in for a builtin: `squad` -> `list`.
        return KEYWORDS.get(node.name, node.name)

    def _e_FStringLiteral(self, node):
        """Rebuild the f-string, regenerating only its replacement fields."""
        fields = getattr(node, "parsed_fields", None)
        if not fields or node.start is None:
            return node.raw

        pieces = []
        cursor = node.start
        for field in fields:
            if field["start"] is None:
                continue
            pieces.append(node.raw[cursor - node.start:field["start"] - node.start])
            pieces.append(self.expression(field["expression"]))
            cursor = field["end"]
        pieces.append(node.raw[cursor - node.start:])
        return "".join(pieces)

    def _e_BinaryExpression(self, node):
        return "({} {} {})".format(self.expression(node.left), node.operator,
                                   self.expression(node.right))

    def _e_UnaryExpression(self, node):
        if node.operator == "not":
            return "(not {})".format(self.expression(node.operand))
        return "({}{})".format(node.operator, self.expression(node.operand))

    def _e_BooleanExpression(self, node):
        joiner = " {} ".format(node.operator)
        return "(" + joiner.join(self.expression(v) for v in node.values) + ")"

    def _e_ComparisonExpression(self, node):
        text = self.expression(node.left)
        for operator, comparator in zip(node.operators, node.comparators):
            text += " {} {}".format(operator, self.expression(comparator))
        return "(" + text + ")"

    def _e_ConditionalExpression(self, node):
        return "({} if {} else {})".format(
            self.expression(node.body), self.expression(node.test),
            self.expression(node.orelse))

    def _e_CallExpression(self, node):
        pieces = [self.expression(arg) for arg in node.args or []]
        pieces += [self.keyword_argument(item) for item in node.keywords or []]
        return "{}({})".format(self.expression(node.callee), ", ".join(pieces))

    def _e_AttributeExpression(self, node):
        # The attribute name is never a keyword, so it is emitted as written.
        return "{}.{}".format(self.expression(node.value), node.name)

    def _e_IndexExpression(self, node):
        return "{}[{}]".format(self.expression(node.value),
                               self.subscript(node.index))

    def subscript(self, node):
        if isinstance(node, N.TupleLiteral) and not node.parenthesised:
            return ", ".join(self.subscript(item) for item in node.elements)
        if isinstance(node, N.SliceExpression):
            return self._e_SliceExpression(node)
        return self.expression(node)

    def _e_SliceExpression(self, node):
        text = self.expression(node.lower) + ":" + self.expression(node.upper)
        if node.step is not None:
            text += ":" + self.expression(node.step)
        return text

    def _e_ListLiteral(self, node):
        return "[" + ", ".join(self.expression(e) for e in node.elements) + "]"

    def _e_TupleLiteral(self, node):
        if not node.elements:
            return "()"
        inside = ", ".join(self.expression(e) for e in node.elements)
        if len(node.elements) == 1:
            inside += ","
        return "(" + inside + ")"

    def _e_SetLiteral(self, node):
        return "{" + ", ".join(self.expression(e) for e in node.elements) + "}"

    def _e_DictLiteral(self, node):
        pieces = []
        for key, value in node.pairs:
            if key is None:
                pieces.append("**" + self.expression(value))
            else:
                pieces.append("{}: {}".format(self.expression(key),
                                              self.expression(value)))
        return "{" + ", ".join(pieces) + "}"

    def _e_Comprehension(self, node):
        if node.kind == "dict":
            head = "{}: {}".format(self.expression(node.element),
                                   self.expression(node.value))
        else:
            head = self.expression(node.element)

        clauses = ""
        for clause in node.clauses:
            clauses += " {}{} {} in {}".format(
                "async " if clause.is_async else "", PY["spam"],
                self.target(clause.target), self.expression(clause.iterable))
            for condition in clause.conditions:
                clauses += " {} {}".format(PY["bet"], self.expression(condition))

        body = head + clauses
        if node.kind == "list":
            return "[" + body + "]"
        if node.kind == "set":
            return "{" + body + "}"
        if node.kind == "dict":
            return "{" + body + "}"
        return "(" + body + ")"

    def _e_LambdaExpression(self, node):
        params = self.parameters(node.params)
        return "(lambda{}: {})".format(" " + params if params else "",
                                       self.expression(node.body))

    def _e_StarredExpression(self, node):
        return ("**" if node.double else "*") + self.expression(node.value)

    def _e_WalrusExpression(self, node):
        return "({} := {})".format(self.expression(node.target),
                                   self.expression(node.value))

    def _e_YieldExpression(self, node):
        if node.is_from:
            return "(yield from {})".format(self.expression(node.value))
        if node.value is None:
            return "(yield)"
        return "(yield {})".format(self.expression(node.value))

    def _e_AwaitExpression(self, node):
        return "(await {})".format(self.expression(node.value))

modules.wpplang/compiler/parser.py:
"""The W++ parser.

Consumes the token stream from the lexer and produces a W++ AST.  Statements
are handled by recursive descent - one method per construct, which keeps each
piece of the grammar readable - and expressions by precedence climbing, so the
precedence table is written once instead of being spread across a dozen
near-identical methods.

W++'s grammar is Python's grammar with nineteen renamed words, so the shape of
this parser follows Python's statement forms.  What makes it a W++ parser is
that `bet`, `plotwist`, `nah`, `spam`, `grind`, `cook`, `spill`, `dip` and
`skrrt` are the words it recognises, and that it records which W++ keyword
opened each construct on the node it builds.
"""

from ..keywords import KEYWORDS
from .errors import WppIndentationError, WppSyntaxError
from .nodes import (
    AnnotatedAssignment, Assignment, AssertStatement, AttributeExpression,
    AugmentedAssignment, AwaitExpression, BinaryExpression, BooleanExpression,
    BreakStatement, CallExpression, ClassDeclaration, ComparisonExpression,
    Comprehension, ComprehensionClause, ConditionalExpression,
    ContinueStatement, DeleteStatement, DictLiteral, ExceptClause,
    ExpressionStatement, FStringLiteral, ForStatement, FunctionDeclaration,
    GlobalStatement, Identifier, IfStatement, ImportAlias, ImportFromStatement,
    ImportStatement, IndexExpression, KeywordArgument, LambdaExpression,
    ListLiteral, Literal, MatchCase, MatchStatement, NonlocalStatement,
    Parameter, PassStatement, Program, RaiseStatement, ReturnStatement,
    SetLiteral, SliceExpression, StarredExpression, TryStatement,
    TupleLiteral, UnaryExpression, WalrusExpression, WhileStatement,
    WithItem, WithStatement, YieldExpression,
)
from .tokens import TokenType

# Binary operator precedence, lowest binding first.  `or` and `and` are handled
# separately because they build BooleanExpression, and comparisons are handled
# separately because W++ keeps Python's chaining.
_BINARY_PRECEDENCE = [
    ("|",),
    ("^",),
    ("&",),
    ("<<", ">>"),
    ("+", "-"),
    ("*", "/", "//", "%", "@"),
]

_COMPARISON_OPS = {"<", ">", "==", ">=", "<=", "!=", "<>"}

_AUGMENTED_OPS = {
    "+=", "-=", "*=", "/=", "//=", "%=", "**=", ">>=", "<<=", "&=", "|=",
    "^=", "@=",
}

# Words W++ leaves as Python's own.  Listed so the parser can tell a statement
# keyword from an ordinary name without guessing.
_STATEMENT_WORDS = {
    "class", "try", "except", "finally", "with", "raise", "assert", "import",
    "from", "global", "nonlocal", "del", "pass", "match", "case", "lambda",
    "yield", "await", "async", "and", "or", "not", "in", "is", "if", "else",
    "for", "while", "return", "def", "break", "continue", "elif",
}


def parse(tokens, source=None):
    """Parse a token stream into a Program."""
    return _Parser(tokens, source).parse_program()


class _Parser:
    def __init__(self, tokens, source=None):
        self.tokens = tokens
        self.index = 0
        self.source = source
        self.lines = source.splitlines() if source else []

    # ------------------------------------------------------------ token access

    @property
    def current(self):
        return self.tokens[self.index]

    def peek(self, offset=1):
        position = min(self.index + offset, len(self.tokens) - 1)
        return self.tokens[position]

    def advance(self):
        token = self.tokens[self.index]
        if self.index < len(self.tokens) - 1:
            self.index += 1
        return token

    def check_op(self, *symbols):
        return self.current.is_op(*symbols)

    def accept_op(self, *symbols):
        if self.current.is_op(*symbols):
            return self.advance()
        return None

    def expect_op(self, symbol, what=None):
        if not self.current.is_op(symbol):
            self.fail("expected {!r}{}".format(
                symbol, " " + what if what else ""))
        return self.advance()

    def accept_keyword(self, *words):
        if self.current.is_keyword(*words):
            return self.advance()
        return None

    def accept_name(self, *names):
        if self.current.is_name(*names):
            return self.advance()
        return None

    def at_word(self, *names):
        """Is the current token one of these bare Python words?"""
        return self.current.is_name(*names)

    def fail_plain(self, message, token=None):
        """Fail with exactly this message, with no "but found ..." added."""
        token = token or self.current
        text = None
        if token.line and 1 <= token.line <= len(self.lines):
            text = self.lines[token.line - 1]
        raise WppSyntaxError(message, line=token.line, column=token.column,
                             source_line=text)

    def reject_keyword_name(self, token, role="a name"):
        """The one mistake every W++ beginner makes, explained properly."""
        self.fail_plain(
            "'{}' is a W++ keyword (it becomes Python's '{}'), so it cannot be "
            "used as {}".format(token.value, KEYWORDS[token.value], role), token)

    def fail(self, message, token=None):
        token = token or self.current
        text = None
        if token.line and 1 <= token.line <= len(self.lines):
            text = self.lines[token.line - 1]

        # An INDENT or DEDENT where a statement was expected is an indentation
        # problem, and the spec has its own message for those.
        if token.type == TokenType.INDENT:
            raise WppIndentationError(
                "unexpected indent", line=token.line,
                column=token.column, source_line=text)
        if token.type == TokenType.DEDENT:
            raise WppIndentationError(
                "unindent does not match any outer indentation level",
                line=token.line, column=token.column, source_line=text)

        shown = token.value if token.type != TokenType.EOF else "the end of the file"
        raise WppSyntaxError(
            "{} but found {!r}".format(message, shown) if shown else message,
            line=token.line, column=token.column, source_line=text)

    # ------------------------------------------------------------- structure

    def parse_program(self):
        body = []
        self.skip_newlines()
        while self.current.type != TokenType.EOF:
            body.append(self.parse_statement())
            self.skip_newlines()
        return Program(body, line=1, column=0)

    def skip_newlines(self):
        while self.current.type in (TokenType.NEWLINE, TokenType.INDENT,
                                    TokenType.DEDENT):
            # A stray INDENT/DEDENT at top level only happens on a blank line
            # that tokenize measured; the block parser consumes the real ones.
            if self.current.type != TokenType.NEWLINE and not self._blank_layout():
                return
            self.advance()

    def _blank_layout(self):
        """True when an INDENT/DEDENT here carries no statement after it."""
        offset = 0
        while self.peek(offset).type in (TokenType.INDENT, TokenType.DEDENT,
                                         TokenType.NEWLINE):
            offset += 1
        return self.peek(offset).type == TokenType.EOF

    def parse_block(self):
        """Parse `: <newline> INDENT statements DEDENT`, or a one-line body."""
        self.expect_op(":", "to open a block")

        if self.current.type != TokenType.NEWLINE:
            # A single-line body: `bet x: yap(1)`.
            return self.parse_simple_line()

        self.advance()  # the NEWLINE
        while self.current.type == TokenType.NEWLINE:
            self.advance()

        if self.current.type != TokenType.INDENT:
            self.fail("expected an indented block")
        self.advance()

        body = []
        while True:
            while self.current.type == TokenType.NEWLINE:
                self.advance()
            if self.current.type in (TokenType.DEDENT, TokenType.EOF):
                break
            body.append(self.parse_statement())
        if self.current.type == TokenType.DEDENT:
            self.advance()
        if not body:
            self.fail("this block is empty")
        return body

    def parse_simple_line(self):
        """One or more small statements separated by semicolons."""
        statements = [self.parse_small_statement()]
        while self.accept_op(";"):
            if self.current.type in (TokenType.NEWLINE, TokenType.EOF):
                break
            statements.append(self.parse_small_statement())
        if self.current.type == TokenType.NEWLINE:
            self.advance()
        return statements

    # ------------------------------------------------------------ statements

    def parse_statement(self):
        token = self.current

        if self.check_op("@"):
            return self.parse_decorated()
        if token.is_keyword("cook"):
            return self.parse_function()
        if token.is_keyword("bet"):
            return self.parse_if()
        if token.is_keyword("spam"):
            return self.parse_for()
        if token.is_keyword("grind"):
            return self.parse_while()
        if token.is_name("class"):
            return self.parse_class()
        if token.is_name("try"):
            return self.parse_try()
        if token.is_name("with"):
            return self.parse_with()
        if token.is_name("match") and self._looks_like_match():
            return self.parse_match()
        if token.is_name("async"):
            return self.parse_async()
        if token.is_name("if", "for", "while", "def", "elif", "else"):
            self.fail("`{}` is Python; W++ uses its own word here".format(token.value))

        statements = self.parse_simple_line()
        return statements[0] if len(statements) == 1 else _Sequence(statements)

    def parse_small_statement(self):
        token = self.current

        if token.is_keyword("spill"):
            return self.parse_return()
        if token.is_keyword("dip"):
            self.advance()
            return BreakStatement("dip", line=token.line, column=token.column)
        if token.is_keyword("skrrt"):
            self.advance()
            return ContinueStatement("skrrt", line=token.line, column=token.column)
        if token.is_name("pass"):
            self.advance()
            return PassStatement(line=token.line, column=token.column)
        if token.is_name("raise"):
            return self.parse_raise()
        if token.is_name("assert"):
            return self.parse_assert()
        if token.is_name("import"):
            return self.parse_import()
        if token.is_name("from"):
            return self.parse_import_from()
        if token.is_name("global", "nonlocal"):
            return self.parse_scope_declaration()
        if token.is_name("del"):
            return self.parse_delete()
        if token.is_name("return", "break", "continue"):
            self.fail("`{}` is Python; W++ uses its own word here".format(token.value))

        return self.parse_assignment_or_expression()

    def parse_decorated(self):
        decorators = []
        while self.check_op("@"):
            at = self.advance()
            decorators.append(self.parse_expression())
            if self.current.type == TokenType.NEWLINE:
                self.advance()
            while self.current.type == TokenType.NEWLINE:
                self.advance()
        if self.current.is_keyword("cook"):
            node = self.parse_function()
        elif self.at_word("class"):
            node = self.parse_class()
        elif self.at_word("async"):
            node = self.parse_async()
        else:
            self.fail("a decorator must be followed by `cook` or `class`", at)
        node.decorators = decorators
        return node

    def parse_async(self):
        word = self.advance()
        if self.current.is_keyword("cook"):
            node = self.parse_function()
            node.is_async = True
            return node
        if self.current.is_keyword("spam"):
            node = self.parse_for()
            node.is_async = True
            return node
        if self.at_word("with"):
            node = self.parse_with()
            node.is_async = True
            return node
        self.fail("`async` must be followed by `cook`, `spam` or `with`", word)

    def parse_function(self):
        keyword = self.advance()  # cook
        name = self.parse_definition_name(keyword)
        self.expect_op("(", "to open the parameter list")
        params = self.parse_parameters()
        self.expect_op(")", "to close the parameter list")

        returns = None
        if self.accept_op("->"):
            returns = self.parse_expression()

        body = self.parse_block()
        return FunctionDeclaration(name, params, body, [], False, returns,
                                   keyword.value,
                                   line=keyword.line, column=keyword.column)

    def parse_definition_name(self, keyword):
        """Read the name a definition is being given.

        A W++ keyword cannot be used here: `cook dip(self)` would have to
        become `def break(self)`, and even if that parsed, a call written
        `dip()` would become `break()`.  Saying so plainly beats letting the
        generated Python fail somewhere the author cannot see.
        """
        token = self.current
        if token.type == TokenType.KEYWORD:
            self.reject_keyword_name(token)
        if token.type != TokenType.NAME:
            self.fail("expected a name after `{}`".format(keyword.value), token)
        return self.advance().value

    def parse_parameters(self):
        params = []
        seen_star = False
        while not self.check_op(")"):
            if self.accept_op("/"):
                for param in params:
                    if param.kind == "normal":
                        param.kind = "positional_only"
                self.accept_op(",")
                continue
            if self.check_op("*") and self.peek().is_op(","):
                self.advance()
                seen_star = True
                self.accept_op(",")
                continue
            if self.accept_op("*"):
                seen_star = True
                params.append(self._one_parameter("vararg"))
                self.accept_op(",")
                continue
            if self.accept_op("**"):
                params.append(self._one_parameter("kwarg"))
                self.accept_op(",")
                continue

            params.append(self._one_parameter(
                "keyword_only" if seen_star else "normal"))
            if not self.accept_op(","):
                break
        return params

    def _one_parameter(self, kind):
        token = self.current
        if token.type == TokenType.KEYWORD:
            self.reject_keyword_name(token, "a parameter name")
        if token.type != TokenType.NAME:
            self.fail("expected a parameter name", token)
        self.advance()

        annotation = None
        if self.accept_op(":"):
            annotation = self.parse_expression()
        default = None
        if self.accept_op("="):
            default = self.parse_expression()
        return Parameter(token.value, default, kind, annotation,
                         line=token.line, column=token.column)

    def parse_class(self):
        keyword = self.advance()
        name = self.parse_definition_name(keyword)
        bases, keywords = [], []
        if self.accept_op("("):
            bases, keywords = self.parse_call_arguments()
            self.expect_op(")", "to close the base class list")
        body = self.parse_block()
        return ClassDeclaration(name, bases, keywords, body, [],
                                line=keyword.line, column=keyword.column)

    def parse_if(self):
        keyword = self.current
        branches = []
        condition = None

        first = self.accept_keyword("bet")
        if first is None:
            self.fail("expected `bet`")
        condition = self.parse_expression()
        branches.append((condition, self.parse_block()))

        orelse = None
        while True:
            self.skip_layout_before_clause(keyword.column)
            if self.current.is_keyword("plotwist"):
                self.advance()
                test = self.parse_expression()
                branches.append((test, self.parse_block()))
                continue
            if self.current.is_keyword("nah"):
                self.advance()
                orelse = self.parse_block()
            break

        return IfStatement(branches, orelse, line=keyword.line, column=keyword.column)

    def skip_layout_before_clause(self, column):
        """Look past blank lines for a clause continuing the statement at `column`.

        `plotwist`, `nah`, `except` and `finally` sit at the same indentation as
        the statement they belong to, so after a block ends the parser peeks
        across the layout tokens to find them.

        Matching the column is what stops a clause being claimed by the wrong
        statement.  In

            spam n in numbers:
                bet n % 2 == 1:
                    dip
            nah:
                yap("all even")

        the `nah` is the loop's, not the `bet`'s - it is written at the loop's
        indentation.  Without the column test the inner `bet` would swallow it
        and the program would mean something else entirely.
        """
        offset = 0
        while self.peek(offset).type in (TokenType.NEWLINE, TokenType.DEDENT):
            offset += 1
        follower = self.peek(offset)
        if follower.column != column:
            return
        if (follower.is_keyword("plotwist", "nah")
                or follower.is_name("except", "finally", "else", "elif")):
            for _ in range(offset):
                self.advance()

    def _looks_like_match(self):
        """Is this bare `match` opening a match statement, or just a name?

        `match` is a soft keyword: `match = 1` and `match(x)` are ordinary code.
        It opens a statement when what follows is a subject expression and the
        logical line ends with a colon.
        """
        after = self.peek()
        if (after.type in (TokenType.NEWLINE, TokenType.EOF)
                or after.is_op("=", ".", ",", ")", "]", "}", ":", ";")
                or (after.type == TokenType.OP and after.value in _AUGMENTED_OPS)):
            return False

        depth = 0
        offset = 1
        while True:
            token = self.peek(offset)
            if token.type in (TokenType.NEWLINE, TokenType.EOF):
                return False
            if token.is_op("(", "[", "{"):
                depth += 1
            elif token.is_op(")", "]", "}"):
                depth -= 1
            elif token.is_op(":") and depth == 0:
                return True
            elif token.is_op("=") and depth == 0:
                return False
            offset += 1

    def parse_for(self):
        keyword = self.advance()  # spam
        target = self.parse_target_list()
        if not self.accept_name("in"):
            self.fail("expected `in` after the loop variable")
        iterable = self.parse_expression_list()
        body = self.parse_block()

        orelse = None
        self.skip_layout_before_clause(keyword.column)
        if self.current.is_keyword("nah"):
            self.advance()
            orelse = self.parse_block()
        return ForStatement(target, iterable, body, orelse, False, keyword.value,
                            line=keyword.line, column=keyword.column)

    def parse_while(self):
        keyword = self.advance()  # grind
        condition = self.parse_expression()
        body = self.parse_block()

        orelse = None
        self.skip_layout_before_clause(keyword.column)
        if self.current.is_keyword("nah"):
            self.advance()
            orelse = self.parse_block()
        return WhileStatement(condition, body, orelse, keyword.value,
                              line=keyword.line, column=keyword.column)

    def parse_return(self):
        keyword = self.advance()  # spill
        value = None
        if self.current.type not in (TokenType.NEWLINE, TokenType.EOF) \
                and not self.check_op(";"):
            value = self.parse_expression_list()
        return ReturnStatement(value, keyword.value,
                               line=keyword.line, column=keyword.column)

    def parse_try(self):
        keyword = self.advance()
        body = self.parse_block()
        handlers = []
        orelse = None
        finalbody = None

        while True:
            self.skip_layout_before_clause(keyword.column)
            if self.at_word("except"):
                handlers.append(self.parse_except())
                continue
            if self.current.is_keyword("nah") or self.at_word("else"):
                self.advance()
                orelse = self.parse_block()
                continue
            if self.at_word("finally"):
                self.advance()
                finalbody = self.parse_block()
            break

        if not handlers and finalbody is None:
            self.fail("a `try` needs an `except` or a `finally`", keyword)
        return TryStatement(body, handlers, orelse, finalbody,
                            line=keyword.line, column=keyword.column)

    def parse_except(self):
        keyword = self.advance()
        is_star = bool(self.accept_op("*"))
        exception = None
        name = None
        if not self.check_op(":"):
            exception = self.parse_expression()
            if self.accept_name("as"):
                name = self.advance().value
        body = self.parse_block()
        return ExceptClause(exception, name, body, is_star,
                            line=keyword.line, column=keyword.column)

    def parse_with(self):
        keyword = self.advance()
        items = []
        parenthesised = bool(self.check_op("(") and self._with_uses_parens())
        if parenthesised:
            self.advance()
        while True:
            context = self.parse_expression()
            target = None
            if self.accept_name("as"):
                target = self.parse_primary_target()
            items.append(WithItem(context, target))
            if not self.accept_op(","):
                break
        if parenthesised:
            self.expect_op(")", "to close the `with` items")
        body = self.parse_block()
        return WithStatement(items, body, False,
                             line=keyword.line, column=keyword.column)

    def _with_uses_parens(self):
        """Distinguish `with (a, b):` grouping from a parenthesised expression."""
        depth = 0
        offset = 0
        while True:
            token = self.peek(offset)
            if token.type == TokenType.EOF:
                return False
            if token.is_op("(", "[", "{"):
                depth += 1
            elif token.is_op(")", "]", "}"):
                depth -= 1
                if depth == 0:
                    return self.peek(offset + 1).is_op(":")
            elif token.is_name("as") and depth == 1:
                return True
            offset += 1

    def parse_match(self):
        keyword = self.advance()
        subject = self.parse_expression_list()
        self.expect_op(":", "to open the match block")
        if self.current.type == TokenType.NEWLINE:
            self.advance()
        while self.current.type == TokenType.NEWLINE:
            self.advance()
        if self.current.type != TokenType.INDENT:
            self.fail("expected an indented block of `case` clauses")
        self.advance()

        cases = []
        while True:
            while self.current.type == TokenType.NEWLINE:
                self.advance()
            if self.current.type in (TokenType.DEDENT, TokenType.EOF):
                break
            if not self.at_word("case"):
                self.fail("expected `case`")
            case_token = self.advance()
            pattern = self.collect_pattern_text()
            guard = None
            if self.current.is_keyword("bet") or self.at_word("if"):
                self.advance()
                guard = self.parse_expression()
            body = self.parse_block()
            cases.append(MatchCase(pattern, guard, body,
                                   line=case_token.line, column=case_token.column))
        if self.current.type == TokenType.DEDENT:
            self.advance()
        if not cases:
            self.fail("a `match` needs at least one `case`", keyword)
        return MatchStatement(subject, cases,
                              line=keyword.line, column=keyword.column)

    def collect_pattern_text(self):
        """Capture a `case` pattern as source text.

        W++ adds nothing to Python's pattern syntax, and patterns are the one
        place where a name means "bind this" rather than "read this", so they
        are carried through as written rather than reinterpreted.
        """
        pieces = []
        depth = 0
        while True:
            token = self.current
            if token.type == TokenType.EOF:
                self.fail("this `case` pattern is never finished")
            if depth == 0 and (token.is_op(":") or token.is_keyword("bet")
                               or token.is_name("if")):
                break
            if token.is_op("(", "[", "{"):
                depth += 1
            elif token.is_op(")", "]", "}"):
                depth -= 1
            pieces.append(token)
            self.advance()
        if not pieces:
            self.fail("this `case` has no pattern")
        return _render_tokens(pieces)

    def parse_raise(self):
        keyword = self.advance()
        exception = None
        cause = None
        if self.current.type not in (TokenType.NEWLINE, TokenType.EOF) \
                and not self.check_op(";"):
            exception = self.parse_expression()
            if self.accept_name("from"):
                cause = self.parse_expression()
        return RaiseStatement(exception, cause,
                              line=keyword.line, column=keyword.column)

    def parse_assert(self):
        keyword = self.advance()
        test = self.parse_expression()
        message = None
        if self.accept_op(","):
            message = self.parse_expression()
        return AssertStatement(test, message,
                               line=keyword.line, column=keyword.column)

    def parse_import(self):
        keyword = self.advance()
        names = []
        while True:
            dotted = self.parse_dotted_name()
            asname = None
            if self.accept_name("as"):
                asname = self.advance().value
            names.append(ImportAlias(dotted, asname))
            if not self.accept_op(","):
                break
        return ImportStatement(names, line=keyword.line, column=keyword.column)

    def parse_import_from(self):
        keyword = self.advance()
        level = 0
        while self.check_op(".", "..."):
            level += len(self.advance().value)
        module = None
        if not self.at_word("import"):
            module = self.parse_dotted_name()
        if not self.accept_name("import"):
            self.fail("expected `import`")

        names = []
        if self.accept_op("*"):
            names.append(ImportAlias("*", None))
        else:
            wrapped = bool(self.accept_op("("))
            while True:
                name = self.advance().value
                asname = None
                if self.accept_name("as"):
                    asname = self.advance().value
                names.append(ImportAlias(name, asname))
                if not self.accept_op(","):
                    break
                if self.check_op(")"):
                    break
            if wrapped:
                self.expect_op(")", "to close the import list")
        return ImportFromStatement(module, names, level,
                                   line=keyword.line, column=keyword.column)

    def parse_dotted_name(self):
        parts = [self.advance().value]
        while self.check_op(".") and self.peek().type in (TokenType.NAME,
                                                          TokenType.KEYWORD):
            self.advance()
            parts.append(self.advance().value)
        return ".".join(parts)

    def parse_scope_declaration(self):
        keyword = self.advance()
        names = [self.advance().value]
        while self.accept_op(","):
            names.append(self.advance().value)
        node = (GlobalStatement if keyword.value == "global" else NonlocalStatement)
        return node(names, line=keyword.line, column=keyword.column)

    def parse_delete(self):
        keyword = self.advance()
        targets = [self.parse_expression()]
        while self.accept_op(","):
            targets.append(self.parse_expression())
        return DeleteStatement(targets, line=keyword.line, column=keyword.column)

    def parse_assignment_or_expression(self):
        start = self.current
        first = self.parse_expression_list(allow_star=True)

        if self.current.type == TokenType.OP and self.current.value in _AUGMENTED_OPS:
            operator = self.advance().value
            value = self.parse_expression_list()
            return AugmentedAssignment(first, operator, value,
                                       line=start.line, column=start.column)

        if self.check_op(":") :
            self.advance()
            annotation = self.parse_expression()
            value = None
            if self.accept_op("="):
                value = self.parse_expression_list()
            return AnnotatedAssignment(first, annotation, value,
                                       line=start.line, column=start.column)

        if self.check_op("="):
            targets = [first]
            value = None
            while self.accept_op("="):
                value = self.parse_expression_list(allow_star=True, allow_yield=True)
                if self.check_op("="):
                    targets.append(value)
            return Assignment(targets, value, line=start.line, column=start.column)

        return ExpressionStatement(first, line=start.line, column=start.column)

    def parse_target_list(self):
        """The `x` or `x, y` between `spam` and `in`."""
        items = [self.parse_primary_target()]
        trailing = False
        while self.accept_op(","):
            if self.at_word("in") or self.check_op(":"):
                trailing = True
                break
            items.append(self.parse_primary_target())
        if len(items) == 1 and not trailing:
            return items[0]
        return TupleLiteral(items, False, line=items[0].line, column=items[0].column)

    def parse_primary_target(self):
        if self.check_op("("):
            open_token = self.advance()
            inner = self.parse_target_list()
            self.expect_op(")", "to close the target")
            return inner
        if self.check_op("["):
            open_token = self.advance()
            items = []
            while not self.check_op("]"):
                items.append(self.parse_primary_target())
                if not self.accept_op(","):
                    break
            self.expect_op("]", "to close the target")
            return ListLiteral(items, line=open_token.line, column=open_token.column)
        if self.accept_op("*"):
            inner = self.parse_primary_target()
            return StarredExpression(inner, False, line=inner.line, column=inner.column)
        return self.parse_unary()

    # ----------------------------------------------------------- expressions

    def parse_expression_list(self, allow_star=False, allow_yield=False):
        """One expression, or a bare tuple like `1, 2`."""
        if allow_yield and self.at_word("yield"):
            return self.parse_yield()

        first = self.parse_expression(allow_star=allow_star)
        if not self.check_op(","):
            return first

        items = [first]
        trailing = True
        while self.accept_op(","):
            if self._at_expression_end():
                break
            items.append(self.parse_expression(allow_star=allow_star))
            trailing = False
        return TupleLiteral(items, False, line=first.line, column=first.column)

    def _at_expression_end(self):
        return (self.current.type in (TokenType.NEWLINE, TokenType.EOF)
                or self.current.is_op(")", "]", "}", ":", "=", ";")
                or self.current.type == TokenType.OP
                and self.current.value in _AUGMENTED_OPS)

    def parse_expression(self, allow_star=False):
        if self.at_word("lambda"):
            return self.parse_lambda()
        if self.at_word("yield"):
            return self.parse_yield()
        if allow_star and self.check_op("*"):
            star = self.advance()
            value = self.parse_expression()
            return StarredExpression(value, False, line=star.line, column=star.column)

        node = self.parse_ternary()

        # The walrus binds looser than everything except a comma.
        if self.check_op(":="):
            self.advance()
            value = self.parse_expression()
            return WalrusExpression(node, value, line=node.line, column=node.column)
        return node

    def parse_ternary(self):
        node = self.parse_or()
        # `value bet condition nah other`, W++'s conditional expression.
        if self.current.is_keyword("bet") or self.at_word("if"):
            self.advance()
            test = self.parse_or()
            if self.current.is_keyword("nah") or self.at_word("else"):
                self.advance()
            else:
                self.fail("a one-line `bet` needs a `nah`")
            orelse = self.parse_expression()
            return ConditionalExpression(node, test, orelse,
                                         line=node.line, column=node.column)
        return node

    def parse_or(self):
        node = self.parse_and()
        if not self.at_word("or"):
            return node
        values = [node]
        while self.accept_name("or"):
            values.append(self.parse_and())
        return BooleanExpression("or", values, line=node.line, column=node.column)

    def parse_and(self):
        node = self.parse_not()
        if not self.at_word("and"):
            return node
        values = [node]
        while self.accept_name("and"):
            values.append(self.parse_not())
        return BooleanExpression("and", values, line=node.line, column=node.column)

    def parse_not(self):
        if self.at_word("not"):
            token = self.advance()
            return UnaryExpression("not", self.parse_not(),
                                   line=token.line, column=token.column)
        return self.parse_comparison()

    def parse_comparison(self):
        node = self.parse_binary(0)
        operators = []
        comparators = []
        while True:
            operator = self._comparison_operator()
            if operator is None:
                break
            comparators.append(self.parse_binary(0))
            operators.append(operator)
        if not operators:
            return node
        return ComparisonExpression(node, operators, comparators,
                                    line=node.line, column=node.column)

    def _comparison_operator(self):
        token = self.current
        if token.type == TokenType.OP and token.value in _COMPARISON_OPS:
            self.advance()
            return token.value
        if token.is_name("in"):
            self.advance()
            return "in"
        if token.is_name("not") and self.peek().is_name("in"):
            self.advance()
            self.advance()
            return "not in"
        if token.is_name("is"):
            self.advance()
            if self.at_word("not"):
                self.advance()
                return "is not"
            return "is"
        return None

    def parse_binary(self, level):
        if level >= len(_BINARY_PRECEDENCE):
            return self.parse_unary()

        node = self.parse_binary(level + 1)
        symbols = _BINARY_PRECEDENCE[level]
        while self.current.type == TokenType.OP and self.current.value in symbols:
            operator = self.advance().value
            right = self.parse_binary(level + 1)
            node = BinaryExpression(node, operator, right,
                                    line=node.line, column=node.column)
        return node

    def parse_unary(self):
        token = self.current
        if token.is_op("-", "+", "~"):
            self.advance()
            return UnaryExpression(token.value, self.parse_unary(),
                                   line=token.line, column=token.column)
        if token.is_name("await"):
            self.advance()
            return AwaitExpression(self.parse_unary(),
                                   line=token.line, column=token.column)
        return self.parse_power()

    def parse_power(self):
        node = self.parse_postfix()
        if self.check_op("**"):
            self.advance()
            # Right associative, and the exponent may itself be signed.
            right = self.parse_unary()
            return BinaryExpression(node, "**", right,
                                    line=node.line, column=node.column)
        return node

    def parse_postfix(self):
        node = self.parse_atom()
        while True:
            if self.check_op("("):
                self.advance()
                args, keywords = self.parse_call_arguments()
                self.expect_op(")", "to close the call")
                node = CallExpression(node, args, keywords,
                                      line=node.line, column=node.column)
                continue
            if self.check_op("["):
                self.advance()
                index = self.parse_subscript()
                self.expect_op("]", "to close the subscript")
                node = IndexExpression(node, index,
                                       line=node.line, column=node.column)
                continue
            if self.check_op("."):
                self.advance()
                name_token = self.current
                if name_token.type not in (TokenType.NAME, TokenType.KEYWORD):
                    self.fail("expected an attribute name after `.`")
                self.advance()
                # After a dot a W++ keyword is just a name, which is why
                # `stack.dip()` keeps working.
                node = AttributeExpression(node, name_token.value,
                                           line=node.line, column=node.column)
                continue
            return node

    def parse_subscript(self):
        items = []
        while True:
            items.append(self.parse_slice_item())
            if not self.accept_op(","):
                break
            if self.check_op("]"):
                items.append(None)
                break
        if len(items) == 1:
            return items[0]
        return TupleLiteral([item for item in items if item is not None], False,
                            line=self.current.line, column=self.current.column)

    def parse_slice_item(self):
        lower = None
        if not self.check_op(":"):
            lower = self.parse_expression(allow_star=True)
            if not self.check_op(":"):
                return lower
        start = self.current
        self.expect_op(":")
        upper = None
        step = None
        if not self.check_op(":", "]", ","):
            upper = self.parse_expression()
        if self.accept_op(":"):
            if not self.check_op("]", ","):
                step = self.parse_expression()
        return SliceExpression(lower, upper, step,
                               line=start.line, column=start.column)

    def parse_call_arguments(self):
        args = []
        keywords = []
        while not self.check_op(")"):
            if self.accept_op("**"):
                keywords.append(KeywordArgument(None, self.parse_expression()))
            elif self.check_op("*"):
                star = self.advance()
                args.append(StarredExpression(self.parse_expression(), False,
                                              line=star.line, column=star.column))
            elif (self.current.type in (TokenType.NAME, TokenType.KEYWORD)
                    and self.peek().is_op("=")
                    and not self.peek().is_op("==")):
                if self.current.type == TokenType.KEYWORD:
                    # `f(bet=1)` would have to become `f(if=1)`.
                    self.reject_keyword_name(self.current,
                                             "a keyword argument name")
                name_token = self.advance()
                self.advance()  # =
                keywords.append(KeywordArgument(name_token.value,
                                                self.parse_expression()))
            else:
                value = self.parse_expression()
                clauses = self.parse_comprehension_clauses()
                if clauses is not None:
                    value = Comprehension("generator", value, None, clauses,
                                          line=value.line, column=value.column)
                args.append(value)
            if not self.accept_op(","):
                break
        return args, keywords

    def parse_comprehension_clauses(self):
        """Read `spam x in xs bet cond` clauses, or return None if absent."""
        if not (self.current.is_keyword("spam") or self.at_word("for")
                or (self.at_word("async") and self.peek().is_keyword("spam"))):
            return None

        clauses = []
        while True:
            is_async = bool(self.accept_name("async"))
            if not (self.accept_keyword("spam") or self.accept_name("for")):
                break
            target = self.parse_target_list()
            if not self.accept_name("in"):
                self.fail("expected `in` in this comprehension")
            iterable = self.parse_or()
            conditions = []
            while self.current.is_keyword("bet") or self.at_word("if"):
                self.advance()
                conditions.append(self.parse_or_no_ternary())
            clauses.append(ComprehensionClause(target, iterable, conditions, is_async))
            if not (self.current.is_keyword("spam") or self.at_word("for")
                    or (self.at_word("async") and self.peek().is_keyword("spam"))):
                break
        return clauses

    def parse_or_no_ternary(self):
        """A comprehension filter: `bet` here is a filter, not a ternary."""
        return self.parse_or()

    def parse_lambda(self):
        token = self.advance()
        params = []
        if not self.check_op(":"):
            params = self.parse_lambda_parameters()
        self.expect_op(":", "to open the lambda body")
        body = self.parse_expression()
        return LambdaExpression(params, body, line=token.line, column=token.column)

    def parse_lambda_parameters(self):
        params = []
        seen_star = False
        while not self.check_op(":"):
            if self.accept_op("*"):
                seen_star = True
                if self.check_op(","):
                    self.advance()
                    continue
                params.append(self._one_lambda_parameter("vararg"))
            elif self.accept_op("**"):
                params.append(self._one_lambda_parameter("kwarg"))
            else:
                params.append(self._one_lambda_parameter(
                    "keyword_only" if seen_star else "normal"))
            if not self.accept_op(","):
                break
        return params

    def _one_lambda_parameter(self, kind):
        token = self.current
        if token.type == TokenType.KEYWORD:
            self.reject_keyword_name(token, "a parameter name")
        self.advance()
        default = None
        if self.accept_op("="):
            default = self.parse_expression()
        return Parameter(token.value, default, kind, None,
                         line=token.line, column=token.column)

    def parse_yield(self):
        token = self.advance()
        if self.accept_name("from"):
            return YieldExpression(self.parse_expression(), True,
                                   line=token.line, column=token.column)
        value = None
        if not self._at_expression_end():
            value = self.parse_expression_list()
        return YieldExpression(value, False, line=token.line, column=token.column)

    def parse_atom(self):
        token = self.current

        if token.type == TokenType.NUMBER:
            self.advance()
            return Literal(None, token.value, "number",
                           line=token.line, column=token.column)

        if token.type == TokenType.STRING:
            # Adjacent literals concatenate, as in Python.
            parts = [self.advance().value]
            while self.current.type == TokenType.STRING:
                parts.append(self.advance().value)
            return Literal(None, " ".join(parts), "string",
                           line=token.line, column=token.column)

        if token.type == TokenType.FSTRING:
            self.advance()
            node = FStringLiteral(token.extra["raw"], token.extra.get("fields"),
                                  token.extra.get("start"),
                                  line=token.line, column=token.column)
            self._parse_fstring_fields(node)
            return node

        if token.type == TokenType.KEYWORD:
            if token.value in ("nocap", "cap", "npc"):
                self.advance()
                return Literal(token.value, token.value, "constant",
                               line=token.line, column=token.column)
            # A keyword such as `squad` or `range` used as a value: it maps to a
            # Python builtin, so it behaves as a name here.
            if token.value in ("squad", "tea", "cult", "range", "bodycount",
                               "yap", "dm"):
                self.advance()
                return Identifier(token.value, line=token.line, column=token.column)
            self.fail("`{}` cannot be used as a value".format(token.value))

        if token.type == TokenType.NAME:
            if token.value in _STATEMENT_WORDS and token.value not in (
                    "None", "True", "False"):
                if token.value not in ("match", "case", "type"):
                    self.fail("`{}` cannot start an expression".format(token.value))
            self.advance()
            return Identifier(token.value, line=token.line, column=token.column)

        if token.is_op("("):
            return self.parse_parenthesised()
        if token.is_op("["):
            return self.parse_list_display()
        if token.is_op("{"):
            return self.parse_brace_display()
        if token.is_op("..."):
            self.advance()
            return Literal(None, "...", "ellipsis",
                           line=token.line, column=token.column)

        self.fail("expected a value")

    def _parse_fstring_fields(self, node):
        """Parse each replacement field of an f-string into an expression."""
        if not node.fields:
            node.parsed_fields = []
            return
        parsed = []
        for field in node.fields:
            tokens = list(field["tokens"])
            if not tokens:
                continue
            from .tokens import Token as _Token
            tokens.append(_Token(TokenType.EOF, "", tokens[-1].end_line,
                                 tokens[-1].end_column))
            inner = _Parser(tokens, self.source)
            expression = inner.parse_expression_list(allow_star=True)
            parsed.append({"start": field["start"], "end": field["end"],
                           "expression": expression})
        node.parsed_fields = parsed

    def parse_parenthesised(self):
        open_token = self.advance()

        if self.check_op(")"):
            self.advance()
            return TupleLiteral([], True, line=open_token.line, column=open_token.column)

        if self.at_word("yield"):
            inner = self.parse_yield()
            self.expect_op(")", "to close the group")
            return inner

        first = self.parse_expression(allow_star=True)

        clauses = self.parse_comprehension_clauses()
        if clauses is not None:
            self.expect_op(")", "to close the generator")
            return Comprehension("generator", first, None, clauses,
                                 line=open_token.line, column=open_token.column)

        if self.check_op(","):
            items = [first]
            while self.accept_op(","):
                if self.check_op(")"):
                    break
                items.append(self.parse_expression(allow_star=True))
            self.expect_op(")", "to close the tuple")
            return TupleLiteral(items, True, line=open_token.line,
                                column=open_token.column)

        self.expect_op(")", "to close the group")
        first.parenthesised = True
        return first

    def parse_list_display(self):
        open_token = self.advance()
        if self.check_op("]"):
            self.advance()
            return ListLiteral([], line=open_token.line, column=open_token.column)

        first = self.parse_expression(allow_star=True)
        clauses = self.parse_comprehension_clauses()
        if clauses is not None:
            self.expect_op("]", "to close the comprehension")
            return Comprehension("list", first, None, clauses,
                                 line=open_token.line, column=open_token.column)

        items = [first]
        while self.accept_op(","):
            if self.check_op("]"):
                break
            items.append(self.parse_expression(allow_star=True))
        self.expect_op("]", "to close the list")
        return ListLiteral(items, line=open_token.line, column=open_token.column)

    def parse_brace_display(self):
        open_token = self.advance()
        if self.check_op("}"):
            self.advance()
            return DictLiteral([], line=open_token.line, column=open_token.column)

        # `{**other}` is a dict; `{*items}` is a set.
        if self.accept_op("**"):
            value = self.parse_or()
            pairs = [(None, value)]
            while self.accept_op(","):
                if self.check_op("}"):
                    break
                pairs.append(self._dict_pair())
            self.expect_op("}", "to close the dict")
            return DictLiteral(pairs, line=open_token.line, column=open_token.column)

        first = self.parse_expression(allow_star=True)

        if self.check_op(":"):
            self.advance()
            first_value = self.parse_expression()
            clauses = self.parse_comprehension_clauses()
            if clauses is not None:
                self.expect_op("}", "to close the comprehension")
                return Comprehension("dict", first, first_value, clauses,
                                     line=open_token.line, column=open_token.column)
            pairs = [(first, first_value)]
            while self.accept_op(","):
                if self.check_op("}"):
                    break
                pairs.append(self._dict_pair())
            self.expect_op("}", "to close the dict")
            return DictLiteral(pairs, line=open_token.line, column=open_token.column)

        clauses = self.parse_comprehension_clauses()
        if clauses is not None:
            self.expect_op("}", "to close the comprehension")
            return Comprehension("set", first, None, clauses,
                                 line=open_token.line, column=open_token.column)

        items = [first]
        while self.accept_op(","):
            if self.check_op("}"):
                break
            items.append(self.parse_expression(allow_star=True))
        self.expect_op("}", "to close the set")
        return SetLiteral(items, line=open_token.line, column=open_token.column)

    def _dict_pair(self):
        if self.accept_op("**"):
            return (None, self.parse_or())
        key = self.parse_expression()
        self.expect_op(":", "between a dict key and its value")
        return (key, self.parse_expression())


class _Sequence:
    """Several small statements written on one line, joined by semicolons."""

    _fields = ("statements",)

    def __init__(self, statements):
        self.statements = statements
        self.line = statements[0].line if statements else None
        self.column = statements[0].column if statements else None

    def dump(self, indent=0):
        pad = "  " * indent
        lines = ["{}Sequence".format(pad)]
        for item in self.statements:
            lines.append(item.dump(indent + 1))
        return "\n".join(lines)


def _render_tokens(tokens):
    """Join tokens back into source text, used only for `case` patterns."""
    pieces = []
    previous = None
    for token in tokens:
        if previous is not None:
            same_line = token.line == previous.end_line
            if not same_line or token.column > previous.end_column:
                pieces.append(" ")
        pieces.append(str(token.value))
        previous = token
    return "".join(pieces)

modules.wpplang/compiler/semantic.py:
"""Semantic validation of a W++ program.

The parser answers "is this W++?".  This stage answers the questions that need
a view of the whole tree: is `dip` inside a loop, is `spill` inside a `cook`,
does anything try to use a keyword as a name.  Catching these here means the
error names the W++ word and the W++ line, instead of arriving later as a
complaint about generated Python.

Deliberately small.  W++ is dynamically typed, so there is no type checking to
do and inventing some would change the language.
"""

from ..keywords import KEYWORDS
from .errors import WppSemanticError
from . import nodes as N


def validate(program, source=None):
    """Check a Program.  Raises WppSemanticError on the first problem."""
    _Checker(source).program(program)
    return program


class _Checker:
    def __init__(self, source=None):
        self.lines = source.splitlines() if source else []

    def fail(self, message, node):
        raise WppSemanticError(
            message, line=node.line, column=node.column,
            source_line=self._text(node.line))

    def _text(self, line):
        if line and 1 <= line <= len(self.lines):
            return self.lines[line - 1]
        return None

    # -- walking

    def program(self, program):
        self.block(program.body, in_loop=False, in_function=False)

    def block(self, body, in_loop, in_function):
        if body is None:
            return
        if not isinstance(body, list):
            body = [body]
        for statement in body:
            self.statement(statement, in_loop, in_function)

    def statement(self, node, in_loop, in_function):
        if isinstance(node, N.BreakStatement):
            if not in_loop:
                self.fail("`dip` only means something inside a `spam` or "
                          "`grind` loop", node)
            return
        if isinstance(node, N.ContinueStatement):
            if not in_loop:
                self.fail("`skrrt` only means something inside a `spam` or "
                          "`grind` loop", node)
            return
        if isinstance(node, N.ReturnStatement):
            if not in_function:
                self.fail("`spill` only means something inside a `cook` "
                          "function", node)
            return

        if isinstance(node, N.FunctionDeclaration):
            self.check_name(node.name, node)
            seen = set()
            for param in node.params:
                self.check_name(param.name, param)
                if param.name in seen:
                    self.fail("`{}` is listed twice in this parameter "
                              "list".format(param.name), param)
                seen.add(param.name)
            # A loop does not reach into a nested function.
            self.block(node.body, in_loop=False, in_function=True)
            return

        if isinstance(node, N.ClassDeclaration):
            self.check_name(node.name, node)
            self.block(node.body, in_loop=False, in_function=in_function)
            return

        if isinstance(node, N.IfStatement):
            for _condition, body in node.branches:
                self.block(body, in_loop, in_function)
            self.block(node.orelse, in_loop, in_function)
            return

        if isinstance(node, N.ForStatement):
            self.block(node.body, in_loop=True, in_function=in_function)
            self.block(node.orelse, in_loop, in_function)
            return

        if isinstance(node, N.WhileStatement):
            self.block(node.body, in_loop=True, in_function=in_function)
            self.block(node.orelse, in_loop, in_function)
            return

        if isinstance(node, N.TryStatement):
            self.block(node.body, in_loop, in_function)
            for handler in node.handlers or []:
                self.block(handler.body, in_loop, in_function)
            self.block(node.orelse, in_loop, in_function)
            self.block(node.finalbody, in_loop, in_function)
            return

        if isinstance(node, N.WithStatement):
            self.block(node.body, in_loop, in_function)
            return

        if isinstance(node, N.MatchStatement):
            for case in node.cases:
                self.block(case.body, in_loop, in_function)
            return

        if isinstance(node, N.Assignment):
            for target in node.targets:
                self.check_target(target)
            return

        if type(node).__name__ == "_Sequence":
            for item in node.statements:
                self.statement(item, in_loop, in_function)
            return

    # -- names

    def check_name(self, name, node):
        """A definition may not be named after a W++ keyword."""
        if name in KEYWORDS:
            self.fail(
                "'{}' is a W++ keyword (it becomes Python's '{}'), so it "
                "cannot be used as a name".format(name, KEYWORDS[name]), node)

    def check_target(self, target):
        """Assigning to a keyword is the same mistake, spelled differently."""
        name = None
        if isinstance(target, N.Identifier) and target.name in KEYWORDS:
            name = target.name
        elif isinstance(target, N.Literal) and target.kind == "constant":
            # `nocap`, `cap` and `npc` parse as values, so they arrive here as
            # literals rather than names - but `cap = 1` is the same mistake,
            # and without this it would reach Python as `False = 1`.
            name = target.value

        if name is not None:
            self.fail(
                "'{}' is a W++ keyword (it becomes Python's '{}'), so it "
                "cannot be assigned to".format(name, KEYWORDS[name]), target)

        if isinstance(target, (N.TupleLiteral, N.ListLiteral)):
            for element in target.elements:
                self.check_target(element)
        elif isinstance(target, N.StarredExpression):
            self.check_target(target.value)

modules.wpplang/errors.py:
"""The Skill Issue Protocol.

Python tracebacks are intercepted and re-presented using the W++ messages from
the spec.  The message wording is fixed by the spec and must not be edited; the
surrounding context (file, line, source line) is ours to add.
"""

import traceback

# Exception class name -> official W++ message.  Wording is verbatim from the
# W++ Language Spec v1.1, section 2.
SKILL_ISSUES = {
    "SyntaxError": "Negative Aura: Bro forgot how to type (SyntaxError)",
    "NameError": "Bro is making up words now (NameError)",
    "TypeError": "Oil up bro, you can't combine those (TypeError)",
    "IndexError": "Blud thinks he has more items than he does (IndexError)",
    "ZeroDivisionError": "Math ain't mathing: Bro tried to divide by zero (ZeroDivisionError)",
    "IndentationError": "Your spaces are looking a little sus (IndentationError)",
    "KeyboardInterrupt": "Go touch grass, you've been looping forever (KeyboardInterrupt)",
}

SIREN = "\U0001f6a8"  # The spec prints every skill issue behind a siren.


def skill_issue_message(exc):
    """Return the official W++ message for an exception.

    The lookup walks the exception's MRO, so subclasses land on the right
    message: IndentationError is a SyntaxError, but it has its own entry and
    the MRO reaches it first.  Anything outside the spec gets a generic line
    rather than a raw Python traceback.
    """
    for klass in type(exc).__mro__:
        if klass.__name__ in SKILL_ISSUES:
            return SKILL_ISSUES[klass.__name__]
    return "Unspecified skill issue ({})".format(type(exc).__name__)


def skill_issue_details(exc, source_path=None, source_lines=None, source_map=None):
    """Describe a skill issue as plain data.

    Returns a dict with the official ``message``, the Python ``exception``
    name, the ``line`` in the .wpp source, that ``source_line`` itself and the
    original Python ``detail``.  The terminal renderer and the web playground
    both build their output from this, so they can never disagree about the
    wording.
    """
    lineno = _locate(exc, source_path)
    # A runtime failure reports the line of the *generated* Python, so ask the
    # compiler's map which W++ line that came from.
    if source_map is not None and lineno is not None:
        lineno = source_map.wpp_line_for(lineno) or lineno
    return {
        "message": skill_issue_message(exc),
        "exception": type(exc).__name__,
        "path": None if source_path is None else str(source_path),
        "line": lineno,
        "column": getattr(exc, "wpp_column", None),
        "source_line": _source_line(source_lines, lineno),
        "detail": _detail(exc),
    }


def format_skill_issue(exc, source_path=None, source_lines=None, source_map=None):
    """Render a full W++ error report for *exc* as terminal text."""
    info = skill_issue_details(exc, source_path, source_lines, source_map)
    lines = ["{} {}".format(SIREN, info["message"])]

    if info["path"] is not None and info["line"] is not None:
        lines.append("   where: {}, line {}".format(info["path"], info["line"]))
        if info["source_line"] is not None:
            lines.append("   {:>4} | {}".format(info["line"], info["source_line"]))
    elif info["path"] is not None:
        lines.append("   where: {}".format(info["path"]))

    if info["detail"]:
        lines.append("   details: {}".format(info["detail"]))

    return "\n".join(lines)


def _locate(exc, source_path):
    """Find the .wpp line number an exception came from, if we can."""
    # Compile-time errors carry the line directly.
    if isinstance(exc, SyntaxError) and exc.lineno:
        return exc.lineno

    # Runtime errors: walk the traceback and keep the innermost frame that is
    # still inside the user's .wpp file.  Line numbers survive translation
    # unchanged, so the frame's lineno is already the W++ line.
    lineno = None
    for frame in traceback.extract_tb(exc.__traceback__):
        if source_path is None or frame.filename == str(source_path):
            lineno = frame.lineno
    return lineno


def _source_line(source_lines, lineno):
    """Return the stripped source line *lineno*, or None if unavailable."""
    if not source_lines or lineno is None or not 1 <= lineno <= len(source_lines):
        return None
    return source_lines[lineno - 1].strip()


def _detail(exc):
    """A short, human-readable version of the original Python complaint."""
    if isinstance(exc, KeyboardInterrupt):
        return ""
    if isinstance(exc, SyntaxError):
        return exc.msg or ""
    return str(exc)

modules.wpplang/runner.py:
"""Execute translated W++ programs.

The pipeline is deliberately thin:

    .wpp source -> translate() -> Python source -> compile() -> exec()

The .wpp path is handed to compile() as the filename, and the compiler's source
map is carried alongside, so a Python exception raised inside generated code is
reported against the W++ line the author wrote rather than a line number in
code they never saw.
"""

import os

from .errors import format_skill_issue, skill_issue_details
from .translator import compile_wpp

# Process exit codes.
EXIT_OK = 0
EXIT_SKILL_ISSUE = 1
EXIT_INTERRUPTED = 130  # Conventional shell code for Ctrl-C.


class Result:
    """Outcome of running a W++ program.

    ``error_report`` is the terminal-ready text used by the CLI;
    ``error_details`` is the same skill issue as plain data, for callers that
    render their own UI (see wpplang.errors.skill_issue_details).
    """

    def __init__(self, exit_code, error_report=None, error_details=None):
        self.exit_code = exit_code
        self.error_report = error_report
        self.error_details = error_details

    @property
    def ok(self):
        return self.error_report is None


def run_source(source, source_path="<wpp>", extra_globals=None):
    """Translate and execute W++ source text.  Never raises for user errors.

    ``extra_globals`` is merged into the program's namespace, where it shadows
    builtins of the same name.  The playground uses it to supply an interactive
    ``input`` (the target of W++'s ``dm``) without touching this module.
    """
    display_path = str(source_path)
    source_lines = source.splitlines()

    source_map = None
    try:
        compiled = compile_wpp(source, display_path)
        source_map = compiled.source_map
        code = compile(compiled.python, display_path, "exec")
    except (SyntaxError, ValueError) as exc:
        # A frontend rejection already carries a W++ line; a SyntaxError from
        # the generated Python would not, so map it back.
        return _failure(EXIT_SKILL_ISSUE, exc, display_path, source_lines,
                        source_map)

    # A fresh namespace that looks like a normal top-level script.
    namespace = {"__name__": "__main__", "__file__": display_path}
    if extra_globals:
        namespace.update(extra_globals)

    try:
        exec(code, namespace)
    except SystemExit as exc:  # `exit(2)` inside a W++ program is not an error.
        return Result(exc.code if isinstance(exc.code, int) else EXIT_OK)
    except KeyboardInterrupt as exc:
        return _failure(EXIT_INTERRUPTED, exc, display_path, source_lines,
                        source_map)
    except BaseException as exc:  # noqa: BLE001 - every failure becomes a skill issue.
        return _failure(EXIT_SKILL_ISSUE, exc, display_path, source_lines,
                        source_map)

    return Result(EXIT_OK)


def _failure(exit_code, exc, display_path, source_lines, source_map=None):
    """Build a Result carrying both renderings of a skill issue."""
    return Result(
        exit_code,
        format_skill_issue(exc, display_path, source_lines, source_map),
        skill_issue_details(exc, display_path, source_lines, source_map),
    )


def run_file(path):
    """Translate and execute a .wpp file."""
    with open(path, "r", encoding="utf-8") as handle:
        source = handle.read()
    return run_source(source, os.fspath(path))
